import { i18n } from 'src/boot/i18n';
import { convertAmountService } from 'src/services';
import { notify } from 'src/components/notifications/notify';
import {
  useAmountFormatStore,
  amountCacheKey,
} from 'src/store/Document/amount_format.store';

export default {
  methods: {
    getConversionFields() {
      return [
        'net_amount',
        'tax_amount',
        'tax_rate',
        'net_amount_2',
        'tax_amount_2',
        'tax_rate_2',
        'net_amount_3',
        'tax_amount_3',
        'tax_rate_3',
      ];
    },
    convertToUSValue(value: string) {
      return value.replace(/,/g, '.');
    },
    convertToDeValue(value: string) {
      return value.toString().replace(/\./g, ',');
    },
    normalizeLocale(locale: string) {
      return locale ? locale.toLowerCase().replace('_', '-') : locale;
    },

    convertPOValuePerLocale(locale: string, value: string) {
      const js_locale = this.normalizeLocale(locale);
      value = value ? value.replace(',', '.') : value;
      return Number(parseFloat(value)).toLocaleString(js_locale, {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      });
    },

    isValidAmount(value: string) {
      //remove spaces
      value = value.replace(/\s/g, '');
      const reg = /^[0-9.,]+$/;
      if (!reg.test(value)) {
        return false;
      }
      return true;
    },

    async convertValueAccordingToLocale(
      value: string,
      sourceLocale: string,
      destLocale: string,
    ) {
      if (!value) {
        return 0;
      }
      // Through the store so per-field calls in the same tick share one request and
      // its cache, rather than each hitting /format_amount.
      const amount_store = useAmountFormatStore();
      if (
        amount_store.hasConvertedAmountInCache(value, destLocale, sourceLocale)
      ) {
        return amount_store.convertion_amount_cache[
          amountCacheKey(value, sourceLocale, destLocale)
        ] as string;
      }

      const formatted = await amount_store.formatValue(
        value,
        sourceLocale,
        destLocale,
      );
      if (
        !amount_store.hasConvertedAmountInCache(value, destLocale, sourceLocale)
      ) {
        notify.error(i18n.t('error_internal_occur'));
        return;
      }

      return formatted;
    },
  },
};
